// Build the Gemini request payload from the widget's incoming data
const body = $input.first().json.body || $input.first().json;
const message = (body.message || '').toString().trim();
const incomingHistory = Array.isArray(body.history) ? body.history : [];
const sessionId = body.sessionId || 'anonymous';

const SYSTEM_PROMPT = `You are the friendly AI assistant embedded on buildwithsanjana.com, ` +
  `the portfolio site of Sanjana, a creative designer, video editor, and content creator. ` +
  `Help visitors understand the services offered (video editing, content creation, graphic/creative ` +
  `design, social media content), speak generally about the kind of work shown in the portfolio, and ` +
  `guide interested visitors toward reaching out via the site's contact section to discuss their project. ` +
  `Keep replies short and warm, 2-4 sentences. Never invent exact prices, availability dates, or client ` +
  `names you don't know - if asked for specifics like that, say pricing/timelines depend on the project ` +
  `and invite them to share details through the contact form so Sanjana can follow up personally.`;

// Convert widget history (role: 'user' | 'bot') into Gemini's contents format (user / model)
const contents = incomingHistory
  .filter((m) => m && m.text)
  .slice(-16)
  .map((m) => ({
    role: m.role === 'user' ? 'user' : 'model',
    parts: [{ text: String(m.text) }]
  }));

// Make sure the newest message is included as the final user turn
contents.push({ role: 'user', parts: [{ text: message }] });

return [
  {
    json: {
      sessionId,
      message,
      geminiBody: {
        system_instruction: { parts: [{ text: SYSTEM_PROMPT }] },
        contents,
        generationConfig: {
          temperature: 0.6,
          maxOutputTokens: 300
        }
      }
    }
  }
];

// Extract plain text reply from Gemini's response and fall back gracefully on error
const geminiResponse = $input.first().json;
const sessionId = $('Build Gemini Payload').first().json.sessionId;

let reply = "Sorry, I'm having trouble responding right now - please try again in a moment.";

try {
  const text = geminiResponse.candidates[0].content.parts[0].text;
  if (text && text.trim()) reply = text.trim();
} catch (e) {
  // keep fallback message; optionally inspect geminiResponse.error for debugging
}

return [{ json: { reply, sessionId } }];
